ALTER TABLE public.market_products ADD COLUMN IF NOT EXISTS image_url text, ADD COLUMN IF NOT EXISTS page integer, ADD COLUMN IF NOT EXISTS bbox jsonb;
CREATE POLICY "Owners upload product images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'product-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Owners update product images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'product-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Owners delete product images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'product-images' AND (storage.foldername(name))[1] = auth.uid()::text);